#include <lcms2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int sample(const cmsUInt16Number in[],cmsUInt16Number out[],void *cargo){(void)cargo;double c=in[0]/65535.,m=in[1]/65535.,y=in[2]/65535.,k=in[3]/65535.;cmsCIELab lab={100*(1-k)*(1-(.2126*c+.7152*m+.0722*y)),40*(m-c),40*(y-m)};cmsFloat2LabEncoded(out,&lab);return 1;}
static int sample_rgb(const cmsUInt16Number in[],cmsUInt16Number out[],void *cargo){(void)cargo;double r=in[0]/65535.,g=in[1]/65535.,b=in[2]/65535.;cmsCIELab lab={100*(.2126*r+.7152*g+.0722*b),40*(r-g),40*(g-b)};cmsFloat2LabEncoded(out,&lab);return 1;}
static void rgb_lut_fixture(const char *prefix){char file[4096];cmsHPROFILE p=cmsCreateProfilePlaceholder(NULL);cmsSetProfileVersion(p,2.1);cmsSetDeviceClass(p,cmsSigInputClass);cmsSetColorSpace(p,cmsSigRgbData);cmsSetPCS(p,cmsSigLabData);cmsSetHeaderRenderingIntent(p,INTENT_RELATIVE_COLORIMETRIC);cmsWriteTag(p,cmsSigMediaWhitePointTag,cmsD50_XYZ());cmsMLU *text=cmsMLUalloc(NULL,1);cmsMLUsetASCII(text,"en","US","Synthetic RGB LUT fixture");cmsWriteTag(p,cmsSigProfileDescriptionTag,text);cmsWriteTag(p,cmsSigCopyrightTag,text);cmsMLUfree(text);cmsPipeline *pipe=cmsPipelineAlloc(NULL,3,3);cmsStage *clut=cmsStageAllocCLut16bit(NULL,5,3,3,NULL);cmsStageSampleCLut16bit(clut,sample_rgb,NULL,0);cmsPipelineInsertStage(pipe,cmsAT_END,clut);cmsWriteTag(p,cmsSigAToB0Tag,pipe);snprintf(file,sizeof(file),"%s-rgb-lut.icc",prefix);cmsSaveProfileToFile(p,file);cmsPipelineFree(pipe);cmsCloseProfile(p);}
static int fixture(const char *prefix){char file[4096];cmsHPROFILE p=cmsCreate_sRGBProfile();snprintf(file,sizeof(file),"%s-srgb.icc",prefix);cmsSaveProfileToFile(p,file);cmsCloseProfile(p);cmsToneCurve *gamma=cmsBuildGamma(NULL,2.2);p=cmsCreateGrayProfile(cmsD50_xyY(),gamma);cmsFreeToneCurve(gamma);snprintf(file,sizeof(file),"%s-gray.icc",prefix);cmsSaveProfileToFile(p,file);cmsCloseProfile(p);
 p=cmsCreateProfilePlaceholder(NULL);cmsSetProfileVersion(p,2.1);cmsSetDeviceClass(p,cmsSigInputClass);cmsSetColorSpace(p,cmsSigCmykData);cmsSetPCS(p,cmsSigLabData);cmsSetHeaderRenderingIntent(p,INTENT_RELATIVE_COLORIMETRIC);cmsWriteTag(p,cmsSigMediaWhitePointTag,cmsD50_XYZ());cmsMLU *text=cmsMLUalloc(NULL,1);cmsMLUsetASCII(text,"en","US","Synthetic test CMYK; no printing characterization");cmsWriteTag(p,cmsSigProfileDescriptionTag,text);cmsWriteTag(p,cmsSigCopyrightTag,text);cmsMLUfree(text);
 cmsPipeline *pipe=cmsPipelineAlloc(NULL,4,3);cmsStage *clut=cmsStageAllocCLut16bit(NULL,5,4,3,NULL);cmsStageSampleCLut16bit(clut,sample,NULL,0);cmsPipelineInsertStage(pipe,cmsAT_END,clut);cmsWriteTag(p,cmsSigAToB0Tag,pipe);snprintf(file,sizeof(file),"%s-cmyk.icc",prefix);int ok=cmsSaveProfileToFile(p,file);cmsPipelineFree(pipe);cmsCloseProfile(p);return!ok;
}
int main(int argc,char **argv){if(argc==3&&!strcmp(argv[1],"fixtures")){rgb_lut_fixture(argv[2]);return fixture(argv[2]);}if(argc!=6)return 2;FILE *f=fopen(argv[1],"rb");if(!f)return 3;fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);unsigned char *b=malloc(n);fread(b,1,n,f);fclose(f);cmsHPROFILE in=cmsOpenProfileFromMem(b,n),out=atoi(argv[4])==32?cmsCreateXYZProfile():cmsCreate_sRGBProfile();unsigned type=atoi(argv[3]),bits=atoi(argv[4]),channels=type==1?3:type==2?4:1;cmsHTRANSFORM t=cmsCreateTransform(in,type==1?TYPE_RGB_16:type==2?TYPE_CMYK_16:TYPE_GRAY_16,out,bits==16?TYPE_RGB_16:bits==32?TYPE_XYZ_FLT:TYPE_RGB_8,INTENT_RELATIVE_COLORIMETRIC,0);if(!t)return 4;f=fopen(argv[2],"rb");fseek(f,0,SEEK_END);long size=ftell(f);rewind(f);unsigned char *source=malloc(size),*dest=malloc(size/channels*6);fread(source,1,size,f);fclose(f);unsigned pixels=size/(channels*2);cmsDoTransform(t,source,dest,pixels);f=fopen(argv[5],"wb");fwrite(dest,1,pixels*3*(bits/8),f);fclose(f);cmsDeleteTransform(t);cmsCloseProfile(in);cmsCloseProfile(out);free(source);free(dest);free(b);return 0;}
